function transform(message, context) {
  var today = new Date();
  var y = today.getFullYear();
  var m = ('0' + (today.getMonth() + 1)).slice(-2);
  var d = ('0' + today.getDate()).slice(-2);
  var term = (context.targetTerm || 'UNKNOWN').replace(/[^A-Za-z0-9]/g, '');
  var dir = context.carnegieSftpPath || '/';
  context.set('outfile', dir + 'MU_Carnegie_FAO_' + term + '_' + y + m + d + '.csv');
  return message;
}
